function hexToRgb(hex) {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result ? {
    r: parseInt(result[1], 16) / 255,
    g: parseInt(result[2], 16) / 255,
    b: parseInt(result[3], 16) / 255
  } : null;
}

function getLinearValue(value) {
  if (value <= 0.03928) {
    return value / 12.92;
  }
  return Math.pow((value + 0.055) / 1.055, 2.4);
}

function getLuminance(hex) {
  const rgb = hexToRgb(hex);
  const r = getLinearValue(rgb.r);
  const g = getLinearValue(rgb.g);
  const b = getLinearValue(rgb.b);
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

function getContrast(textHex, bgHex) {
  const textLum = getLuminance(textHex);
  const bgLum = getLuminance(bgHex);
  const lighter = Math.max(textLum, bgLum);
  const darker = Math.min(textLum, bgLum);
  return ((lighter + 0.05) / (darker + 0.05)).toFixed(2);
}

const pairs = [
  { name: "success", text: "#2e7d5b", bg: "#e3f0ea" },
  { name: "info", text: "#0e5249", bg: "#e4efec" },
