// WCAG contrast ratio calculation
function hexToRgb(hex) {
  const r = parseInt(hex.substring(1, 3), 16);
  const g = parseInt(hex.substring(3, 5), 16);
  const b = parseInt(hex.substring(5, 7), 16);
  return {r: r/255, g: g/255, b: b/255};
}

function getLuminance(hex) {
  const {r, g, b} = hexToRgb(hex);

  // Apply gamma correction
  const rs = r <= 0.03928 ? r / 12.92 : Math.pow((r + 0.055) / 1.055, 2.4);
  const gs = g <= 0.03928 ? g / 12.92 : Math.pow((g + 0.055) / 1.055, 2.4);
  const bs = b <= 0.03928 ? b / 12.92 : Math.pow((b + 0.055) / 1.055, 2.4);

  // Relative luminance
  return 0.2126 * rs + 0.7152 * gs + 0.0722 * bs;
}

function contrast(text, bg) {
  const l1 = getLuminance(text);
  const l2 = getLuminance(bg);
  const lighter = Math.max(l1, l2);
  const darker = Math.min(l1, l2);
  return (lighter + 0.05) / (darker + 0.05);
}

// Test all 5 tones
const tests = [
  {tone: "success", text: "#2e7d5b", bg: "#e3f0ea"},
  {tone: "info", text: "#0e5249", bg: "#e4efec"},
  {tone: "alert", text: "#b23a2e", bg: "#f7e6e3"},
  {tone: "warning", text: "#c4732c", bg: "#fbebd9"},
  {tone: "neutral", text: "#6b6259", bg: "#f4eee5"},
];

console.log("WCAG AA requires 4.5:1 for normal text\n");
tests.forEach(t => {
  const ratio = contrast(t.text, t.bg);
  const pass = ratio >= 4.5 ? "PASS ✓" : "FAIL ✗";
  console.log(`${t.tone.padEnd(10)} ${t.text} on ${t.bg}: ${ratio.toFixed(2)}:1  ${pass}`);
});
